package com.fetch.desktop.youtube

import com.fetch.desktop.player.autosync.CueParser
import com.fetch.tv.data.youtube.YouTubeCaptionCue
import com.fetch.tv.data.youtube.YouTubeCaptionTrack
import com.fetch.tv.data.youtube.YouTubeCaptions
import kotlinx.serialization.Serializable

// Reading tracks and cues is shared with the TV (shared/.../YouTubeCaptions.kt). Fetch draws the
// cues itself in the player's subtitle style, as the TV does; WebVTT is for mpv when that fails.

/** "English", "English (auto-generated)", "German (auto-translated)": the TV's labels. */
val YouTubeCaptionTrack.label: String
    get() = when {
        isTranslated -> "$name (auto-translated)"
        isAutoGenerated -> "$name (auto-generated)"
        else -> name
    }

/** The track's first link, asked for as WebVTT, which mpv reads. */
val YouTubeCaptionTrack.webVttUrl: String?
    get() = urls.firstOrNull()?.let { YouTubeCaptions.withFormat(it, "vtt") }

/** Whether captions were on for the last video, and in which language: the TV's caption preference. */
@Serializable
data class YouTubeCaptionPreference(
    val enabled: Boolean = false,
    val languageCode: String? = null
)

/**
 * A track's cues: from the first of its links that gives any, as YouTube's json3 (the TV's
 * format), else as WebVTT. Empty when none do.
 */
fun youTubeCaptionCues(track: YouTubeCaptionTrack, download: (String) -> String?): List<YouTubeCaptionCue> =
    YouTubeCaptions.cues(track, download) { url ->
        download(YouTubeCaptions.withFormat(url, "vtt"))
            ?.let(CueParser::parse)
            ?.map { YouTubeCaptionCue(it.startMs, it.endMs, it.text) }
    }
